'use strict';
const {chromium}=require('playwright');
const assert=require('node:assert/strict');
const path=require('node:path');
const fs=require('node:fs');
const http=require('node:http');
(async()=>{
 const root=path.resolve(__dirname,'..');
 const server=http.createServer((req,res)=>{const name=path.join(root,decodeURIComponent(req.url.split('?')[0]==='/'?'/index.html':req.url.split('?')[0]));if(!name.startsWith(root+path.sep)){res.writeHead(403);return res.end();}try{res.setHeader('Content-Type',name.endsWith('.js')?'text/javascript':name.endsWith('.css')?'text/css':'text/html');res.end(fs.readFileSync(name));}catch(e){res.writeHead(404);res.end();}});
 await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
 try{
 const page=await browser.newPage({viewport:{width:1440,height:1100},acceptDownloads:true});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.clock.install();
 await page.goto('http://127.0.0.1:'+server.address().port+'/');
 assert.equal(await page.getByRole('button',{name:'自动演示',exact:true}).count(),1,'自动演示入口必须存在');
 assert.match(await page.locator('#simulation-banner').innerText(),/模拟.*未连接机床/);
 await page.getByRole('button',{name:'自动演示',exact:true}).click();
 await page.clock.runFor(72000);
 const s=await page.evaluate(()=>ITLApp.lab.snapshot());
 assert.ok(s.windows.filter(w=>w.kind==='thermal'&&w.valid).length>=3);
 assert.ok(s.lastXYZ.every(Number.isFinite));assert.equal(s.bus.maxConcurrent,1);
 assert.equal(await page.locator('#group').isDisabled(),true);
 await page.screenshot({path:path.resolve(__dirname,'../../.prototype-work/preview.png'),fullPage:true});
 await page.getByRole('button',{name:'实验记录',exact:true}).click();
 const downloadEvent=page.waitForEvent('download');
 await page.getByRole('button',{name:'原始数据 CSV',exact:true}).click();
 const download=await downloadEvent;const data=fs.readFileSync(await download.path(),'utf8');
 assert.match(data,/actual_time_iso/);assert.match(data,/simulation_time_s/);assert.match(data,/simulation/);
 await page.getByRole('button',{name:'实时采集',exact:true}).click();
 await page.getByRole('button',{name:'模拟通信失败',exact:true}).click();await page.clock.runFor(1000);
 assert.equal(await page.evaluate(()=>ITLApp.lab.snapshot().phase),'FAULT');
 await page.getByRole('button',{name:'恢复采集',exact:true}).click();
 assert.equal(await page.evaluate(()=>ITLApp.lab.snapshot().baselineReady),true);
 assert.equal(await page.evaluate(()=>ITLApp.lab.snapshot().confirmations.stopped),false);
 await page.getByRole('button',{name:'设备配置',exact:true}).click();
 assert.match(await page.locator('#devices').innerText(),/未核实/);
 await page.getByRole('button',{name:'实时采集',exact:true}).click();
 page.on('dialog',dialog=>dialog.accept());
 await page.getByRole('button',{name:'自动演示',exact:true}).click();
 await page.clock.runFor(19000);
 await page.getByRole('button',{name:'模拟探头超程',exact:true}).click();await page.clock.runFor(1000);
 assert.equal(await page.evaluate(()=>ITLApp.autoDemo),false,'无效窗口应停止自动演示并允许手动纠正');
 assert.equal(await page.evaluate(()=>ITLApp.lab.snapshot().windows.at(-1).valid),false);
 await page.getByRole('button',{name:'新建实验',exact:true}).click();
 await page.locator('#group').selectOption('AC');
 assert.equal(await page.locator('#baseline').isDisabled(),true);
 for(const id of ['stopped','positioned','oriented'])await page.locator('#'+id).check();
 await page.getByRole('button',{name:'建立冷态基准',exact:true}).click();await page.clock.runFor(7000);
 await page.getByRole('button',{name:'开始运行',exact:true}).click();await page.clock.runFor(4000);
 await page.getByRole('button',{name:'返回检测位',exact:true}).click();
 assert.equal(await page.locator('#measure').isDisabled(),true);
 for(const id of ['stopped','positioned','oriented'])await page.locator('#'+id).check();
 await page.getByRole('button',{name:'记录热位移',exact:true}).click();await page.clock.runFor(7000);
 const manual=await page.evaluate(()=>ITLApp.lab.snapshot());
 assert.equal(manual.windows.filter(w=>w.kind==='thermal'&&w.valid).length,1);
 assert.deepEqual(manual.command,[60,60,0,0,60,60]);
 assert.equal(errors.length,0,errors.join('\n'));
 console.log('PASS: local offline UI, auto demo ≥3 valid windows, single owner, CSV download, fault/recovery, failed auto window, manual AC workflow, config, no JS errors');
 }finally{await browser.close();server.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});
